  "inlineSchema": "// Desafio Elite Dev - Plataforma de Eventos e Ingressos\n// Postgres + Prisma\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// Enums\n// ---------------------------------------------------------------------------\n\nenum Role {\n  ORGANIZER\n  CUSTOMER\n  GATE\n}\n\nenum EventStatus {\n  DRAFT\n  PUBLISHED\n  CANCELLED\n}\n\n/// De onde veio o item do catalogo. MANUAL = organizador digitou tudo.\nenum CatalogSource {\n  TMDB\n  TICKETMASTER\n  MANUAL\n}\n\n/// SEATED  = setor numerado, tem linhas em Seat (mapa de assentos)\n/// GENERAL = pista, controlado por capacity/sold\nenum SectorKind {\n  SEATED\n  GENERAL\n}\n\nenum OrderStatus {\n  PENDING\n  PAID\n  DECLINED\n  EXPIRED\n  CANCELLED\n}\n\n/// HELD      = reservado temporariamente, ainda nao pago\n/// CONFIRMED = pago, ocupa o lugar em definitivo\n/// RELEASED  = devolvido ao estoque (expirou ou foi cancelado)\nenum OrderItemStatus {\n  HELD\n  CONFIRMED\n  RELEASED\n}\n\nenum TicketStatus {\n  VALID\n  USED\n  CANCELLED\n}\n\n// ---------------------------------------------------------------------------\n// Identidade\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  role         Role\n  createdAt    DateTime @default(now())\n\n  events      Event[]  @relation(\"OrganizerEvents\")\n  orders      Order[]\n  validations Ticket[] @relation(\"ValidatedBy\")\n}\n\n// ---------------------------------------------------------------------------\n// Catalogo e evento\n// ---------------------------------------------------------------------------\n\nmodel Event {\n  id          String @id @default(uuid())\n  organizerId String\n  organizer   User   @relation(\"OrganizerEvents\", fields: [organizerId], references: [id])\n\n  title      String\n  synopsis   String?\n  imageUrl   String?\n  /// Identidade do item no provedor externo. Guardado para nao refazer\n  /// a chamada e para o painel do organizador saber a origem.\n  source     CatalogSource @default(MANUAL)\n  externalId String?\n\n  venue    String\n  city     String\n  startsAt DateTime\n  doorsAt  DateTime?\n  status   EventStatus @default(DRAFT)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  sectors Sector[]\n  orders  Order[]\n  tickets Ticket[]\n\n  @@index([status, startsAt])\n  @@index([source, externalId])\n}\n\n/// Um evento tem N setores. O setor decide como o lugar e vendido.\nmodel Sector {\n  id      String @id @default(uuid())\n  eventId String\n  event   Event  @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  name       String\n  kind       SectorKind\n  priceCents Int\n\n  /// Usados apenas quando kind = GENERAL.\n  /// O overbooking em pista e barrado por UPDATE condicional em `sold`,\n  /// nao por contagem de linhas.\n  capacity Int?\n  sold     Int  @default(0)\n\n  seats Seat[]\n  items OrderItem[]\n\n  @@unique([eventId, name])\n}\n\n/// Existe apenas em setor SEATED. Uma linha por poltrona.\nmodel Seat {\n  id       String @id @default(uuid())\n  sectorId String\n  sector   Sector @relation(fields: [sectorId], references: [id], onDelete: Cascade)\n\n  row    String\n  number Int\n\n  /// Reserva temporaria. Vence sozinha, sem depender de job.\n  lockedByOrderId String?\n  lockedUntil     DateTime?\n\n  items OrderItem[]\n\n  @@unique([sectorId, row, number])\n  @@index([lockedUntil])\n}\n\n// ---------------------------------------------------------------------------\n// Reserva e pagamento\n// ---------------------------------------------------------------------------\n\nmodel Order {\n  id         String @id @default(uuid())\n  customerId String\n  customer   User   @relation(fields: [customerId], references: [id])\n  eventId    String\n  event      Event  @relation(fields: [eventId], references: [id])\n\n  status     OrderStatus @default(PENDING)\n  totalCents Int         @default(0)\n  /// Janela de checkout. Depois disso os locks caem.\n  expiresAt  DateTime\n  createdAt  DateTime    @default(now())\n\n  items    OrderItem[]\n  payments Payment[]\n\n  @@index([status, expiresAt])\n}\n\nmodel OrderItem {\n  id       String  @id @default(uuid())\n  orderId  String\n  order    Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  sectorId String\n  sector   Sector  @relation(fields: [sectorId], references: [id])\n  /// Nulo em setor GENERAL: a compra e por quantidade, sem lugar marcado.\n  seatId   String?\n  seat     Seat?   @relation(fields: [seatId], references: [id])\n\n  status     OrderItemStatus @default(HELD)\n  priceCents Int\n\n  ticket Ticket?\n\n  @@index([seatId, status])\n}\n\n/// Tentativas de cobranca simulada, aprovadas e recusadas.\n/// Guardar as recusas permite mostrar o caminho de erro na avaliacao.\nmodel Payment {\n  id      String @id @default(uuid())\n  orderId String\n  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  amountCents Int\n  approved    Boolean\n  reason      String?\n  cardLast4   String?\n  createdAt   DateTime @default(now())\n}\n\n// ---------------------------------------------------------------------------\n// Ingresso\n// ---------------------------------------------------------------------------\n\nmodel Ticket {\n  id          String    @id @default(uuid())\n  orderItemId String    @unique\n  orderItem   OrderItem @relation(fields: [orderItemId], references: [id])\n  eventId     String\n  event       Event     @relation(fields: [eventId], references: [id])\n\n  /// Codigo curto digitavel na portaria quando a camera falha.\n  /// Alfabeto sem caracteres ambiguos (sem 0/O, sem 1/I/L).\n  code       String @unique\n  /// Token separado do codigo: quem tem o link ve o ingresso,\n  /// mas o link nao e o segredo que a portaria confere.\n  shareToken String @unique\n  holderName String\n\n  status        TicketStatus @default(VALID)\n  usedAt        DateTime?\n  validatedById String?\n  validatedBy   User?        @relation(\"ValidatedBy\", fields: [validatedById], references: [id])\n\n  issuedAt DateTime @default(now())\n\n  @@index([eventId, status])\n}\n\n// ---------------------------------------------------------------------------\n// Migration manual necessaria (Prisma nao gera indice unico parcial):\n//\n//   CREATE UNIQUE INDEX order_items_seat_confirmed_uniq\n//     ON \"OrderItem\" (\"seatId\")\n//     WHERE \"status\" = 'CONFIRMED' AND \"seatId\" IS NOT NULL;\n//\n// Rede de seguranca no banco: mesmo que a logica de aplicacao falhe,\n// o mesmo assento nunca fica confirmado em duas ordens.\n// ---------------------------------------------------------------------------\n",
